#!/usr/bin/env bash
# Tribute · publish the newest TTS export (generated by "Tribute - TTS Export").
# Run from Git Bash:   cd ~/tribute-tts && bash publish.sh
# It runs from a temporary copy of itself: unpacking the export and catching up with GitHub both replace publish.sh,
# and on Windows the file bash is running must not change under it.
if [ -z "$TRIBUTE_PUBLISH_DIR" ]; then
  TRIBUTE_PUBLISH_DIR="$(cd "$(dirname "$0")" && pwd)"; export TRIBUTE_PUBLISH_DIR
  TRIBUTE_PUBLISH_TMP="$(mktemp 2>/dev/null || echo "$HOME/tribute-publish-$$.sh")"; export TRIBUTE_PUBLISH_TMP
  cp -f "$0" "$TRIBUTE_PUBLISH_TMP" && exec bash "$TRIBUTE_PUBLISH_TMP" "$@"
  TRIBUTE_PUBLISH_TMP=""
fi
main() {
set -e
[ -z "$TRIBUTE_PUBLISH_TMP" ] || trap 'rm -f "$TRIBUTE_PUBLISH_TMP"' EXIT
cd "$TRIBUTE_PUBLISH_DIR"
REPO_URL="https://github.com/RedDjinnPro/tribute-tts.git"
if ! git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  echo "This folder is not a copy (clone) of the asset repo, so there is nothing to publish from."
  echo "On a new computer, run this once in Git Bash, then publish again:"
  echo "  git clone $REPO_URL ~/tribute-tts"
  exit 1
fi
# A computer that has never made a git commit has no name for one: give this folder a name, or the commit below fails.
[ -n "$(git config user.email)" ] || git config user.email "tribute-publisher@users.noreply.github.com"
[ -n "$(git config user.name)" ] || git config user.name "Tribute publisher"
# The newest export zip: Downloads, OneDrive's Downloads, or wherever Windows keeps the Downloads folder.
DIRS=("$HOME/Downloads" "$HOME/OneDrive/Downloads")
if command -v cygpath >/dev/null 2>&1; then
  [ -z "$USERPROFILE" ] || DIRS+=("$(cygpath -u "$USERPROFILE")/Downloads")
  if command -v powershell.exe >/dev/null 2>&1; then
    KD=$(powershell.exe -NoProfile -Command "(New-Object -ComObject Shell.Application).NameSpace('shell:Downloads').Self.Path" 2>/dev/null | tr -d '\r' || true)
    [ -z "$KD" ] || DIRS+=("$(cygpath -u "$KD")")
  fi
fi
ZIP=""
for D in "${DIRS[@]}"; do
  for F in "$D"/tribute-tts-export*.zip; do
    if [ -f "$F" ] && { [ -z "$ZIP" ] || [ "$F" -nt "$ZIP" ]; }; then ZIP="$F"; fi
  done
done
if [ -z "$ZIP" ]; then echo "No tribute-tts-export zip in Downloads. On the export page click Build export, then Download zip, then run this again."; exit 1; fi
BR=$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo main)
# Another computer may have published since this one last did. If nothing here is unpublished, take GitHub's files
# first, so this export lands on top of them: a mini or warzone published from the other computer is kept, not deleted.
if git fetch -q origin 2>/dev/null; then
  if git rev-parse -q --verify "origin/$BR" >/dev/null && git merge-base --is-ancestor HEAD "origin/$BR" 2>/dev/null; then
    git reset -q --hard "origin/$BR"
  fi
else
  echo "Could not reach GitHub to check for newer files. Publishing anyway."
fi
echo "Unpacking: $ZIP"
if command -v unzip >/dev/null 2>&1; then
  unzip -o -q "$ZIP" -d .
else
  powershell.exe -NoProfile -Command "Expand-Archive -Force -LiteralPath '$(cygpath -w "$ZIP")' -DestinationPath '$(cygpath -w "$PWD")'"
fi
git add -A
# Commits here that never reached GitHub while GitHub moved on: commit on top of GitHub's latest (the newest export wins).
if git rev-parse -q --verify "origin/$BR" >/dev/null; then
  git reset -q --soft "origin/$BR"
  git add -A
fi
if git diff --cached --quiet; then
  echo "No new files since the last publish."
else
  git commit -q -m "Publish $(date '+%Y-%m-%d %H:%M')"
fi
# Push every time: a commit whose push failed earlier would otherwise sit unpushed forever.
git config http.postBuffer 524288000
if [ -n "$(git log --oneline @{u}..HEAD 2>/dev/null)" ] || ! git rev-parse @{u} >/dev/null 2>&1; then
  echo "Pushing to GitHub..."
  if ! git push -u -q origin HEAD; then
    echo ""
    echo "PUSH FAILED: GitHub did not receive this export, so TTS will report missing images."
    echo "The save was NOT installed. Fix the error above, then run bash publish.sh again."
    exit 1
  fi
  echo "Published."
else
  echo "GitHub is already up to date."
fi
# The save loads its images from GitHub Pages, which rebuilds after each push: wait until it serves this version.
BASE=$(grep -o '"base": *"[^"]*"' manifest.json | head -n 1 | cut -d'"' -f4)
VER=$(grep -o '"version": *"[^"]*"' manifest.json | head -n 1 | cut -d'"' -f4)
case "$BASE" in *github.io*)
  if command -v curl >/dev/null 2>&1; then
    echo "Waiting for GitHub Pages to serve $VER..."
    LIVE=0
    for i in $(seq 1 40); do
      if curl -fsSL "$BASE""manifest.json?t=$(date +%s)" 2>/dev/null | grep -qF "$VER"; then LIVE=1; break; fi
      sleep 6
    done
    if [ "$LIVE" = "1" ]; then echo "Live: $BASE"; else
      echo ""
      echo "GitHub Pages is not serving this version yet (checked for 4 minutes)."
      echo "First publish? Turn Pages on once: github.com > the repo > Settings > Pages >"
      echo "  Source: Deploy from a branch > Branch: main, folder: / (root) > Save."
      echo "Then wait a minute and load the save; TTS shows no images until Pages is live."
      echo ""
    fi
  fi;;
esac
# The TTS Saves folder: Documents, OneDrive's Documents, or wherever Windows keeps Documents on this computer.
CANDS=("$HOME/Documents/My Games/Tabletop Simulator/Saves" "$HOME/OneDrive/Documents/My Games/Tabletop Simulator/Saves")
if command -v powershell.exe >/dev/null 2>&1 && command -v cygpath >/dev/null 2>&1; then
  MD=$(powershell.exe -NoProfile -Command "[Environment]::GetFolderPath('MyDocuments')" 2>/dev/null | tr -d '\r' || true)
  [ -z "$MD" ] || CANDS+=("$(cygpath -u "$MD")/My Games/Tabletop Simulator/Saves")
fi
DONE="|"
for D in "${CANDS[@]}"; do
  [ -d "$D" ] || continue
  case "$DONE" in *"|$D|"*) continue;; esac
  DONE="$DONE$D|"
  cp -f Tribute.json "$D/TS_Save_7700.json"
  cp -f Tribute.png "$D/TS_Save_7700.png" 2>/dev/null || true
  echo "Save installed: $D/TS_Save_7700.json"
done
if [ "$DONE" = "|" ]; then
  echo "Could not find the Tabletop Simulator Saves folder. Start TTS once on this computer (that makes the folder), then run this again,"
  echo "or copy Tribute.json into it by hand, renamed to TS_Save_7700.json."
fi
echo "Done. In TTS: Games > Save & Load > Tribute."
}
main "$@"; exit $?
